def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    feasible = rem >= 0
    if not np.any(feasible):
        return np.full_like(bins, -np.inf, dtype=float)
    max_cap = np.max(bins)
    is_empty = (bins == max_cap)
    used_mask = feasible & ~is_empty
    scores = np.where(feasible, np.exp(-rem) * (1.0 - rem / (max_cap + 1e-6)), -np.inf)
    if np.any(used_mask):
        fullest_used_idx = np.where(used_mask, bins, -1.0).argmax()
        scores[fullest_used_idx] += 2.0
    return scores
